file.content:
/* Badge pill text */
.badgePillText {
  margin: 0;
  font-size: 12px;
  line-height: 32px;
}

.newPriceSec {
  background-color: #fff;
  margin-bottom: 0;
  padding: 80px 5% 20px;
  display: block;
  position: relative;
}

/* Pricing page variant: transparent bg + 4rem top padding */
.newPriceSecPage {
  background-color: transparent;
  padding-top: 4rem;
}

.containerLarge3 {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
}

.priceTitleGrid {
  display: grid;
  grid-column-gap: 24px;
  grid-row-gap: 24px;
  grid-template-rows: auto;
  grid-template-columns: 1fr;
  place-items: center;
  margin-bottom: 20px;
}

.maxWidthSmall4 {
  width: 100%;
  max-width: 550px;
}

.priceSubheadOut {
  grid-column-gap: 10px;
  grid-row-gap: 10px;
  justify-content: center;
  align-items: center;
  display: flex;
}

.pricesubott {
  background-color: var(--color-accent-bg);
  border: 1px solid var(--color-brand-cyan);
  border-radius: 20px;
  margin-bottom: 17px;
  padding: 0 13px;
  line-height: 14px;
}

.faqSkyText {
  color: var(--color-brand-cyan);
  text-transform: capitalize;
  -webkit-text-fill-color: transparent;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  background-clip: text;
  font-weight: 500;
}

.heading2 {
  color: var(--color-text-primary);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 40px;
  text-align: center;
  line-height: 45px;
  margin-top: 0;
  margin-bottom: 10px;
}

.paragraph {
  color: #000;
  font-size: 16px;
  line-height: 28px;
  text-align: center;
  margin-bottom: 0;
}

/* Tabs menu */
.pricingTabsMenuLarge {
  grid-column-gap: 6px;
  grid-row-gap: 6px;
  background-color: var(--color-brand-light-bg);
  border-style: none;
  border-color: var(--color-brand-card-hover);
  border-radius: 10px;
  justify-content: center;
  align-items: center;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: 24px;
  padding: 5px 7px;
  display: inline-flex;
  width: fit-content;
}

/* Wrapper to center the inline-flex tabs container */
.pricingTabsMenuWrap {
  display: flex;
  justify-content: center;
}

.pricingTabLink {
  grid-column-gap: 8px;
  grid-row-gap: 8px;
  color: #5b616e;
  background-color: transparent;
  border-radius: 10px;
  justify-content: center;
  align-items: center;
  width: 100%;
  min-width: 170px;
  height: 45px;
  padding: 8px 10px;
  font-size: 16px;
  font-weight: 500;
  line-height: 24px;
  display: flex;
  cursor: pointer;
  border: none;
  font-family: var(--font-roobert), Arial, sans-serif;
  transition: color 0.3s, background-color 0.3s;
}

.pricingTabLink:hover {
  color: #030711;
  background-color: transparent;
}

.pricingTabLinkMonthly {
  min-width: 130px;
}

.pricingTabLinkActive {
  color: #082753;
  background-color: #fff;
  background-image: none;
  border-radius: 10px;
  min-width: 170px;
  height: 45px;
  font-size: 16px;
  font-weight: 700;
  font-family: var(--font-roobert), Arial, sans-serif;
  box-shadow: 0 0 80px rgba(0, 0, 0, 0.1);
}

.priceTabText {
  color: var(--color-text-primary);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-weight: 500;
}

.pricingBadge {
  color: #18c958;
  text-align: center;
  background-color: rgba(39, 211, 102, 0.1);
  background-image: none;
  border-radius: 5px;
  justify-content: center;
  align-items: center;
  padding: 2px 8px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 12px;
  font-weight: 500;
  line-height: 20px;
  display: block;
}

/* Pricing grid */
.pricingGrid {
  display: grid;
  grid-column-gap: 16px;
  grid-row-gap: 16px;
  grid-template-rows: auto;
  grid-template-columns: 1fr 1fr 1fr;
  padding-left: 5px;
  padding-right: 5px;
}

/* Cards */
.pricingCard2 {
  grid-column-gap: 15px;
  grid-row-gap: 15px;
  background-color: var(--color-cyan-tint);
  border: 1px solid rgba(33, 207, 255, 0.21);
