  }

  .pricingGrid {
    grid-template-columns: 1fr;
  }

  .pricingCard2,
  .pricingCard2WhiteCard {
    margin-top: 0;
  }

  .paragraphRegular14 {
    width: 100%;
  }

  .pricingTableCell {
