    height: auto;
    padding-top: 2px;
    padding-bottom: 6px;
  }

  /* Webflow line 30564: pricing-tab-link-large.montthly at 479px */
  .pricingTabLinkMonthly {
    min-width: auto;
  }

  /* Webflow line 31922: price-tab-text at 479px → font-size: 14px */
  .priceTabText {
    font-size: 14px;
  }

  /* Webflow line 29707: heading-2.margin-top-0 at 479px → 23px/30px */
  .heading2 {
    font-size: 23px;
    line-height: 30px;
  }

